import{_ as r,o as t,c as a,a3 as o}from"./chunks/framework.DBpCFmh2.js";const m=JSON.parse('{"title":"记忆与 RAG API","description":"本项目采用双进程架构：Chrome 扩展端（Manifest V3）通过本地 HTTP/WebSocket 调用 Agent（Node.js）提供的能力；Agent 源码修改后必须重启进程，新接口才生效。","frontmatter":{"title":"记忆与 RAG API","description":"本项目采用双进程架构：Chrome 扩展端（Manifest V3）通过本地 HTTP/WebSocket 调用 Agent（Node.js）提供的能力；Agent 源码修改后必须重启进程，新接口才生效。"},"headers":[],"relativePath":"API-参考文档/Agent-HTTP-API/记忆与-RAG-API/index.md","filePath":"API-参考文档/Agent-HTTP-API/记忆与-RAG-API/index.md","lastUpdated":null}'),i={name:"API-参考文档/Agent-HTTP-API/记忆与-RAG-API/index.md"};function l(s,e,c,d,n,g){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="记忆与-rag-api" tabindex="-1">记忆与 RAG API <a class="header-anchor" href="#记忆与-rag-api" aria-label="Permalink to &quot;记忆与 RAG API&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js" target="_blank" rel="noreferrer">agent/src/memory/routes.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js" target="_blank" rel="noreferrer">agent/src/memory/service.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/tags.js" target="_blank" rel="noreferrer">agent/src/memory/tags.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/tier.js" target="_blank" rel="noreferrer">agent/src/memory/tier.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js" target="_blank" rel="noreferrer">agent/src/rag/routes.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js" target="_blank" rel="noreferrer">agent/src/rag/searcher.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/docs/RAG-Knowledge-Retrieval-Design.md" target="_blank" rel="noreferrer">docs/RAG-Knowledge-Retrieval-Design.md</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.zh-CN.md" target="_blank" rel="noreferrer">agent/README.zh-CN.md</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#简介">简介</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能考虑">性能考虑</a></li><li><a href="#故障诊断指南">故障诊断指南</a></li><li><a href="#结论">结论</a></li><li><a href="#附录api-参考">附录：API 参考</a></li></ol><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>本参考文档面向“长期记忆管理”和“检索增强生成（RAG）知识库”两套能力，覆盖以下目标：</p><ul><li>说明记忆管理端点 <code>/api/memory/add</code>、<code>/api/memory/query</code>、<code>/api/memory/tags</code>、<code>/api/memory/tier</code> 的调用方式、参数、状态码与错误处理。</li><li>说明 RAG 检索端点 <code>/api/rag/search</code>、<code>/api/rag/index</code>、<code>/api/rag/documents</code> 的行为、配置项与使用示例。</li><li>解释混合检索引擎：语义搜索、关键词匹配、结果重排序（RRF）。</li><li>说明向量嵌入生成、文档分块策略与索引构建流程。</li><li>提供完整的 API 调用示例、参数配置选项、性能优化建议与故障诊断方法。</li></ul><p>本项目采用双进程架构：Chrome 扩展端（Manifest V3）通过本地 HTTP/WebSocket 调用 Agent（Node.js）提供的能力；Agent 源码修改后必须重启进程，新接口才生效。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.zh-CN.md#L477-L520" target="_blank" rel="noreferrer">agent/README.zh-CN.md#L477-L520</a></li></ul><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>记忆与 RAG 功能集中在 Agent 端的 <code>agent/src/memory</code> 与 <code>agent/src/rag</code> 两个子系统中，由统一 HTTP 服务器 <code>server.js</code> 进行认证、CORS、请求体解析与路由分发。</p><pre class="mermaid">graph TB
Client[&quot;客户端Chrome 扩展 / 本地脚本&quot;] --&gt; Server[&quot;HTTP 服务器&lt;br/&gt;agent/src/server.js&quot;]
Server --&gt; MemoryRouter[&quot;记忆路由&lt;br/&gt;agent/src/memory/routes.js&quot;]
Server --&gt; RagRouter[&quot;RAG 路由&lt;br/&gt;agent/src/rag/routes.js&quot;]
MemoryRouter --&gt; MemoryService[&quot;记忆服务&lt;br/&gt;agent/src/memory/service.js&quot;]
MemoryService --&gt; Tags[&quot;标签逻辑&lt;br/&gt;agent/src/memory/tags.js&quot;]
MemoryService --&gt; Tier[&quot;召回档位&lt;br/&gt;agent/src/memory/tier.js&quot;]
RagRouter --&gt; Searcher[&quot;检索器&lt;br/&gt;agent/src/rag/searcher.js&quot;]
Searcher --&gt; Store[&quot;向量存储适配器&quot;]
Searcher --&gt; Embedding[&quot;嵌入提供者&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L548" target="_blank" rel="noreferrer">agent/src/server.js#L417-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L149-L199" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L149-L199</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L133-L282" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L133-L282</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L143-L150" target="_blank" rel="noreferrer">agent/src/memory/service.js#L143-L150</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L27-L38" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L27-L38</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L548" target="_blank" rel="noreferrer">agent/src/server.js#L417-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L1-L200" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L1-L200</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L1-L283" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L1-L283</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li><strong>HTTP 服务器与认证层</strong>：负责 Bearer Token 校验、CORS、JSON body 解析、Multipart 上传、健康检查与通用错误响应。</li><li><strong>记忆服务</strong>：实现记忆的增删改查、会话级去重、关键词检索、可选语义通道、标签名次加成、价值评估与压缩淘汰。</li><li><strong>RAG 路由与管理器</strong>：实现知识库 CRUD、文档导入、单库/跨库检索、安装检测、嵌入连通性测试。</li><li><strong>混合检索器</strong>：向量相似度 + 关键词命中抬分 + 旁路探测 + 阈值过滤。</li><li><strong>标签与召回档位</strong>：标签在有查询时仅做名次加成；无查询时作为唯一选择器；召回档位根据 embedding 配置与 RAG 依赖决定 none/remote/local。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L548" target="_blank" rel="noreferrer">agent/src/server.js#L417-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L1-L20" target="_blank" rel="noreferrer">agent/src/memory/service.js#L1-L20</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L1-L21" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L1-L21</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L1-L26" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L1-L26</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/tags.js#L1-L12" target="_blank" rel="noreferrer">agent/src/memory/tags.js#L1-L12</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/tier.js#L1-L38" target="_blank" rel="noreferrer">agent/src/memory/tier.js#L1-L38</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>下图展示一次典型“跨知识库语义检索”的请求路径：客户端经 Bearer Token 访问 <code>/api/rag/search</code>，服务器完成认证后交给 RAG 路由，路由再调用管理器执行跨库检索；每个知识库内部使用 Searcher 进行向量检索与关键词增强，最终合并返回。</p><pre class="mermaid">sequenceDiagram
participant C as &quot;客户端&quot;
participant S as &quot;HTTP 服务器&lt;br/&gt;server.js&quot;
participant R as &quot;RAG 路由&lt;br/&gt;rag/routes.js&quot;
participant M as &quot;RAG 管理器&quot;
participant SR as &quot;检索器&lt;br/&gt;searcher.js&quot;
participant ST as &quot;向量存储&quot;
participant E as &quot;嵌入提供者&quot;
C-&gt;&gt;S : POST /api/rag/search {collectionIds, query, topK, threshold}
S-&gt;&gt;S : 校验 Bearer Token
S-&gt;&gt;R : ragRouter(req, res, pathname, url, t, body)
R-&gt;&gt;M : searchMulti(collectionIds, query, options)
loop 每个知识库
M-&gt;&gt;SR : search(query, options)
SR-&gt;&gt;E : embedQuery(query)
E--&gt;&gt;SR : 查询向量
SR-&gt;&gt;ST : search(queryVector, query, {topK*2})
ST--&gt;&gt;SR : 候选结果
SR-&gt;&gt;SR : _boostByKeywords(query, candidates)
SR-&gt;&gt;SR : 阈值过滤 + 旁路探测
SR--&gt;&gt;M : 单库结果
end
M--&gt;&gt;R : 跨库合并结果
R--&gt;&gt;S : {success, results, total, hasContext, fallback}
S--&gt;&gt;C : JSON 响应
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L537-L548" target="_blank" rel="noreferrer">agent/src/server.js#L537-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L175-L186" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L175-L186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L46-L77" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L46-L77</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L537-L548" target="_blank" rel="noreferrer">agent/src/server.js#L537-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L175-L186" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L175-L186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L46-L77" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L46-L77</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="记忆管理端点" tabindex="-1">记忆管理端点 <a class="header-anchor" href="#记忆管理端点" aria-label="Permalink to &quot;记忆管理端点&quot;">​</a></h3><p>记忆端点由 <code>memoryDispatch</code> 统一分发，支持 store/recall/manage/injectSelect/reindex 等动作，并附带 embedding 配置与探活端点。</p><h4 id="api-memory-store-添加-更新-删除记忆" tabindex="-1"><code>/api/memory/store</code>（添加/更新/删除记忆） <a class="header-anchor" href="#api-memory-store-添加-更新-删除记忆" aria-label="Permalink to &quot;\`/api/memory/store\`（添加/更新/删除记忆）&quot;">​</a></h4><ul><li>方法：POST</li><li>用途：新增事实或摘要、更新已有记忆、按 id 删除记忆。</li><li>关键行为： <ul><li>写入前校验 action/type/content/importance 等字段。</li><li>对 add/update 内容执行注入模式拦截，命中提示注入短语直接拒绝。</li><li>带 sessionId 的写入有进程内频率上限，防止批量投毒。</li><li>写成功后异步补向量（懒补），失败不阻塞主流程。</li><li>删除时会同步清理派生向量缓存，避免孤儿向量。</li></ul></li><li>成功响应：<code>{ success: true, message, memory/action/stats }</code></li><li>业务失败：HTTP 400，<code>{ success: false, error, code? }</code></li><li>未匹配路径：HTTP 404，<code>{ success: false, error: &quot;unknownApiPath&quot; }</code></li></ul><p>调用示例（概念描述）：</p><ul><li>添加事实：POST <code>/api/memory/store</code>，body 包含 <code>action: &quot;add&quot;</code>、<code>type: &quot;fact&quot;</code>、<code>content</code>、可选 <code>tags</code>、<code>importance</code>、<code>sourceSessionId</code>。</li><li>更新记忆：POST <code>/api/memory/store</code>，body 包含 <code>action: &quot;update&quot;</code>、<code>memoryId</code>、可选 <code>content/tags/importance/category/title</code>。</li><li>删除记忆：POST <code>/api/memory/store</code>，body 包含 <code>action: &quot;delete&quot;</code>、<code>memoryId</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L149-L199" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L149-L199</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L266-L443" target="_blank" rel="noreferrer">agent/src/memory/service.js#L266-L443</a></li></ul><h4 id="api-memory-recall-查询记忆" tabindex="-1"><code>/api/memory/recall</code>（查询记忆） <a class="header-anchor" href="#api-memory-recall-查询记忆" aria-label="Permalink to &quot;\`/api/memory/recall\`（查询记忆）&quot;">​</a></h4><ul><li>方法：POST</li><li>用途：从长期记忆中检索相关信息，支持关键词通道与可选语义通道融合。</li><li>关键行为： <ul><li>支持 <code>query</code>、<code>tags</code>、<code>memoryType</code>、<code>limit</code>。</li><li>无向量通道时走纯关键词匹配；有向量通道时走 RRF 排名融合。</li><li>标签在有查询时仅做名次加成；无查询时作为唯一选择器。</li><li>会话级去重：同一 sessionId 重复返回的记忆会被优先替换为未召回过的条目。</li><li>访问计数在收尾阶段重读真源后安全写回。</li></ul></li><li>成功响应：<code>{ success: true, message, results, total, query, tier, vectorMatched }</code></li><li>业务失败：HTTP 400，<code>{ success: false, error }</code></li></ul><p>调用示例（概念描述）：</p><ul><li>普通查询：POST <code>/api/memory/recall</code>，body 包含 <code>query</code>、可选 <code>tags</code>、<code>memoryType</code>、<code>limit</code>、<code>sessionId</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L149-L199" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L149-L199</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L461-L740" target="_blank" rel="noreferrer">agent/src/memory/service.js#L461-L740</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/tags.js#L1-L63" target="_blank" rel="noreferrer">agent/src/memory/tags.js#L1-L63</a></li></ul><h4 id="api-memory-manage-审查与压缩" tabindex="-1"><code>/api/memory/manage</code>（审查与压缩） <a class="header-anchor" href="#api-memory-manage-审查与压缩" aria-label="Permalink to &quot;\`/api/memory/manage\`（审查与压缩）&quot;">​</a></h4><ul><li>方法：POST</li><li>用途：review（计算价值分数并返回淘汰建议）、compact（淘汰低价值记忆）。</li><li>关键行为： <ul><li>review 输出所有记忆的价值分数，低于阈值的标记为候选淘汰。</li><li>compact 实际执行淘汰，并维护 stats/version/updatedAt。</li></ul></li><li>成功响应：<code>{ success: true, ... }</code></li><li>业务失败：HTTP 400，<code>{ success: false, error }</code></li></ul><p>调用示例（概念描述）：</p><ul><li>审查：POST <code>/api/memory/manage</code>，body 包含 <code>action: &quot;review&quot;</code>。</li><li>压缩：POST <code>/api/memory/manage</code>，body 包含 <code>action: &quot;compact&quot;</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L149-L199" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L149-L199</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L742-L800" target="_blank" rel="noreferrer">agent/src/memory/service.js#L742-L800</a></li></ul><h4 id="api-memory-embedding-config-记忆嵌入配置" tabindex="-1"><code>/api/memory/embedding-config</code>（记忆嵌入配置） <a class="header-anchor" href="#api-memory-embedding-config-记忆嵌入配置" aria-label="Permalink to &quot;\`/api/memory/embedding-config\`（记忆嵌入配置）&quot;">​</a></h4><ul><li>GET：返回脱敏后的当前配置（隐藏 apiKey，保留 hasApiKey）。</li><li>POST：保存新的 embedding 配置，返回脱敏后的配置。</li><li>非法模式：返回 400，<code>{ success: false, error: &quot;invalidEmbeddingMode&quot; }</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L77-L98" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L77-L98</a></li></ul><h4 id="api-memory-test-embedding-记忆嵌入连通性测试" tabindex="-1"><code>/api/memory/test-embedding</code>（记忆嵌入连通性测试） <a class="header-anchor" href="#api-memory-test-embedding-记忆嵌入连通性测试" aria-label="Permalink to &quot;\`/api/memory/test-embedding\`（记忆嵌入连通性测试）&quot;">​</a></h4><ul><li>方法：POST</li><li>用途：用临时配置调用一次 embedQuery，返回实际维度，用于验证远端向量服务连通性。</li><li>超时保护：默认 8 秒，超时返回 400，<code>{ success: false, error: &quot;embedding_timeout&quot; }</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L100-L116" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L100-L116</a></li></ul><h4 id="api-memory-vector-status-向量缓存状态" tabindex="-1"><code>/api/memory/vector-status</code>（向量缓存状态） <a class="header-anchor" href="#api-memory-vector-status-向量缓存状态" aria-label="Permalink to &quot;\`/api/memory/vector-status\`（向量缓存状态）&quot;">​</a></h4><ul><li>方法：GET</li><li>用途：返回向量缓存是否 stale、已索引条数等只读状态。</li><li>成功响应：<code>{ success: true, ...data }</code></li><li>失败响应：HTTP 400，<code>{ success: false, error }</code></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L118-L134" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L118-L134</a></li></ul><h4 id="api-memory-reindex-重建向量缓存" tabindex="-1"><code>/api/memory/reindex</code>（重建向量缓存） <a class="header-anchor" href="#api-memory-reindex-重建向量缓存" aria-label="Permalink to &quot;\`/api/memory/reindex\`（重建向量缓存）&quot;">​</a></h4><ul><li>方法：POST</li><li>用途：显式为全部记忆重建向量缓存，模型变更后或首次启用向量档后调用一次。</li><li>行为：若向量通道关闭则返回 skipped；若读取失败返回 400；后台失败会记录日志但整体仍可报告部分成功。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L173-L175" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L173-L175</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L890-L912" target="_blank" rel="noreferrer">agent/src/memory/service.js#L890-L912</a></li></ul><h4 id="关于-api-memory-add、-api-memory-query、-api-memory-tags、-api-memory-tier" tabindex="-1">关于 <code>/api/memory/add</code>、<code>/api/memory/query</code>、<code>/api/memory/tags</code>、<code>/api/memory/tier</code> <a class="header-anchor" href="#关于-api-memory-add、-api-memory-query、-api-memory-tags、-api-memory-tier" aria-label="Permalink to &quot;关于 \`/api/memory/add\`、\`/api/memory/query\`、\`/api/memory/tags\`、\`/api/memory/tier\`&quot;">​</a></h4><ul><li>代码中的记忆业务入口是 <code>/api/memory/store</code>、<code>/api/memory/recall</code>、<code>/api/memory/manage</code>、<code>/api/memory/embedding-config</code>、<code>/api/memory/test-embedding</code>、<code>/api/memory/vector-status</code>、<code>/api/memory/reindex</code>。</li><li>扩展端工具层将 <code>store</code>、<code>recall</code>、<code>manage</code> 映射到对应端点；<code>inject</code> 由系统提示词分级注入直接调用。</li><li>因此，“添加记忆”应使用 <code>/api/memory/store</code>（action=add），“查询记忆”应使用 <code>/api/memory/recall</code>，“标签管理”通过 recall 的 tags 参数与 manage 的 review/compact 配合，“层级管理”通过 embedding-config 与 tier 判定逻辑控制。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L19-L27" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L19-L27</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-memory.js#L31-L36" target="_blank" rel="noreferrer">src/background/tool-memory.js#L31-L36</a></li></ul><h3 id="rag-检索端点" tabindex="-1">RAG 检索端点 <a class="header-anchor" href="#rag-检索端点" aria-label="Permalink to &quot;RAG 检索端点&quot;">​</a></h3><p>RAG 路由仅在 RAG 依赖可用时按需加载，所有受保护端点需 Bearer Token。</p><h4 id="api-rag-search-跨知识库检索" tabindex="-1"><code>/api/rag/search</code>（跨知识库检索） <a class="header-anchor" href="#api-rag-search-跨知识库检索" aria-label="Permalink to &quot;\`/api/rag/search\`（跨知识库检索）&quot;">​</a></h4><ul><li>方法：POST</li><li>用途：跨多个知识库执行语义检索；未指定 collectionIds 时搜索全部启用库。</li><li>参数： <ul><li><code>collectionIds</code>：数组，显式指定要检索的知识库 ID。</li><li><code>query</code>：检索文本。</li><li><code>topK</code>：返回结果数量预算。</li><li><code>threshold</code>：语义阈值。</li></ul></li><li>行为： <ul><li>显式 IDs 原样放行，即使库被停用也可检索（@ 手动引用链路）。</li><li>未指定 IDs 时跳过 disabled 库。</li><li>多库时 topK 配额按库均分，保证每个被引用的库都有结果。</li></ul></li><li>成功响应：<code>{ success: true, results, total, hasContext, fallback }</code></li><li>业务失败：HTTP 400，<code>{ success: false, error, code? }</code></li></ul><p>调用示例（概念描述）：</p><ul><li>跨库检索：POST <code>/api/rag/search</code>，body 包含 <code>collectionIds</code>、<code>query</code>、<code>topK</code>、<code>threshold</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L175-L186" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L175-L186</a></li></ul><h4 id="api-rag-collections-id-search-单库检索" tabindex="-1"><code>/api/rag/collections/{id}/search</code>（单库检索） <a class="header-anchor" href="#api-rag-collections-id-search-单库检索" aria-label="Permalink to &quot;\`/api/rag/collections/{id}/search\`（单库检索）&quot;">​</a></h4><ul><li>方法：POST</li><li>用途：对单个知识库执行检索。</li><li>参数：<code>query</code>、<code>topK</code>、<code>threshold</code>。</li><li>成功响应：<code>{ success: true, results, total, hasContext, fallback }</code></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L271-L277" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L271-L277</a></li></ul><h4 id="api-rag-collections-知识库管理" tabindex="-1"><code>/api/rag/collections</code>（知识库管理） <a class="header-anchor" href="#api-rag-collections-知识库管理" aria-label="Permalink to &quot;\`/api/rag/collections\`（知识库管理）&quot;">​</a></h4><ul><li>GET：列出所有知识库（脱敏 embeddingConfig）。</li><li>POST：创建知识库。</li><li>PUT：更新名称/描述/向量配置；向量空间变更自动触发后台重建。</li><li>DELETE：删除知识库。</li><li>POST <code>{id}/toggle</code>：启用/停用知识库。</li><li>GET <code>{id}/stats</code>：文档数/分块数统计。</li><li>GET <code>{id}/documents</code>：文档列表。</li><li>DELETE <code>{id}/documents/{docId}</code>：删除文档。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L165-L226" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L165-L226</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L228-L269" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L228-L269</a></li></ul><h4 id="api-rag-collections-id-ingest-文档导入" tabindex="-1"><code>/api/rag/collections/{id}/ingest</code>（文档导入） <a class="header-anchor" href="#api-rag-collections-id-ingest-文档导入" aria-label="Permalink to &quot;\`/api/rag/collections/{id}/ingest\`（文档导入）&quot;">​</a></h4><ul><li>方法：POST</li><li>用途：导入 text/file/url 三种类型文档，同步执行；进度可通过 <code>/ingest/status</code> 轮询。</li><li>参数：<code>type</code>、<code>metadata</code>、<code>chunkConfig</code>，以及按类型区分的 content/path/url。</li><li>成功响应：<code>{ success: true, ... }</code></li><li>不支持类型：HTTP 400，<code>{ success: false, error: &quot;unsupportedType&quot;, code: &quot;unsupportedType&quot; }</code></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L233-L253" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L233-L253</a></li></ul><h4 id="api-rag-collections-id-ingest-status-导入进度" tabindex="-1"><code>/api/rag/collections/{id}/ingest/status</code>（导入进度） <a class="header-anchor" href="#api-rag-collections-id-ingest-status-导入进度" aria-label="Permalink to &quot;\`/api/rag/collections/{id}/ingest/status\`（导入进度）&quot;">​</a></h4><ul><li>方法：GET</li><li>用途：轮询导入进度快照；无任务时 progress 为 null。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L256-L259" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L256-L259</a></li></ul><h4 id="api-rag-status、-api-rag-test-embedding、-api-rag-install、-api-rag-detect" tabindex="-1"><code>/api/rag/status</code>、<code>/api/rag/test-embedding</code>、<code>/api/rag/install</code>、<code>/api/rag/detect</code> <a class="header-anchor" href="#api-rag-status、-api-rag-test-embedding、-api-rag-install、-api-rag-detect" aria-label="Permalink to &quot;\`/api/rag/status\`、\`/api/rag/test-embedding\`、\`/api/rag/install\`、\`/api/rag/detect\`&quot;">​</a></h4><ul><li><code>/api/rag/status</code>：返回 available 与 install 状态。</li><li><code>/api/rag/test-embedding</code>：测试远端向量服务连通性，返回 mode/model/dimensions。</li><li><code>/api/rag/install</code>：触发白名单依赖安装。</li><li><code>/api/rag/detect</code>：重新检测 RAG 依赖可用性。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L139-L163" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L139-L163</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.zh-CN.md#L488-L510" target="_blank" rel="noreferrer">agent/README.zh-CN.md#L488-L510</a></li></ul><h3 id="混合检索引擎" tabindex="-1">混合检索引擎 <a class="header-anchor" href="#混合检索引擎" aria-label="Permalink to &quot;混合检索引擎&quot;">​</a></h3><p>混合检索由两条通道组成：</p><ul><li><strong>语义通道</strong>：使用 embeddingProvider.embedQuery 生成查询向量，再通过向量存储检索候选。</li><li><strong>关键词通道</strong>：自建中英文匹配，英文/数字按词边界匹配，中文取最长命中片段；高频单元剔除；命中 chunk 保底分 + 单元加分。</li><li><strong>重排序</strong>：RRF（Reciprocal Rank Fusion），关键词与向量各排各的名次，按 <code>1/(60 + rank)</code> 合并，不比较绝对分数。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;开始检索&quot;]) --&gt; Embed[&quot;生成查询向量&quot;]
Embed --&gt; VectorSearch[&quot;向量检索 topK*2&quot;]
VectorSearch --&gt; KeywordBoost[&quot;关键词命中增强&quot;]
KeywordBoost --&gt; Threshold[&quot;阈值过滤&quot;]
Threshold --&gt; Empty{&quot;结果为空？&quot;}
Empty --&gt; |否| Return[&quot;返回 topK 结果&quot;]
Empty --&gt; |是| Fallback[&quot;旁路探测放宽阈值&quot;]
Fallback --&gt; FallbackEmpty{&quot;放宽后为空？&quot;}
FallbackEmpty --&gt; |否| Return
FallbackEmpty --&gt; |是| NoResult[&quot;返回空结果&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L46-L77" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L46-L77</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L89-L160" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L89-L160</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L1-L26" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L1-L26</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L46-L77" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L46-L77</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L89-L160" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L89-L160</a></li></ul><h3 id="向量嵌入生成" tabindex="-1">向量嵌入生成 <a class="header-anchor" href="#向量嵌入生成" aria-label="Permalink to &quot;向量嵌入生成&quot;">​</a></h3><ul><li>本地模式：默认使用 Xenova/bge-small-zh-v1.5，512 维，经 transformers 本地运行。</li><li>远端模式：OpenAI 兼容端点，支持连通性测试并返回实际维度。</li><li>记忆侧与 RAG 侧共用 embedding 工厂，但记忆侧额外支持 lazy backfill 与 backfillVectors 重建。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.zh-CN.md#L483-L486" target="_blank" rel="noreferrer">agent/README.zh-CN.md#L483-L486</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L148-L163" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L148-L163</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L194-L212" target="_blank" rel="noreferrer">agent/src/memory/service.js#L194-L212</a></li></ul><h3 id="文档分块策略" tabindex="-1">文档分块策略 <a class="header-anchor" href="#文档分块策略" aria-label="Permalink to &quot;文档分块策略&quot;">​</a></h3><ul><li>默认 chunkSize=400，overlap=80，separator=&#39;\\n\\n&#39;。</li><li>先按段落切，再合并到接近 chunkSize；单段超长强制按字符切；硬上限 500 字符。</li><li>返回 chunks 包含 startPos/endPos，为 BM25 混合检索预留。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/docs/RAG-Knowledge-Retrieval-Design.md#L708-L721" target="_blank" rel="noreferrer">docs/RAG-Knowledge-Retrieval-Design.md#L708-L721</a></li></ul><h3 id="索引构建流程" tabindex="-1">索引构建流程 <a class="header-anchor" href="#索引构建流程" aria-label="Permalink to &quot;索引构建流程&quot;">​</a></h3><ul><li>文档解析：text/md/json/csv/html/pdf/office 等格式由对应 parser 输出纯文本。</li><li>分块：chunker 按策略切分。</li><li>向量化：embeddingProvider 生成向量。</li><li>存储：VectraStore 使用 LocalIndex，beginUpdate/endUpdate 事务包裹逐条 upsertItem，失败 cancelUpdate。</li><li>重建：向量空间或分块参数变更时后台自动重建，临时目录重放 → 原子换入。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/docs/RAG-Knowledge-Retrieval-Design.md#L695-L707" target="_blank" rel="noreferrer">docs/RAG-Knowledge-Retrieval-Design.md#L695-L707</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/docs/RAG-Knowledge-Retrieval-Design.md#L786-L860" target="_blank" rel="noreferrer">docs/RAG-Knowledge-Retrieval-Design.md#L786-L860</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><p>记忆与 RAG 模块之间的耦合关系如下：</p><ul><li>server.js 负责认证与通用路由，不关心具体业务。</li><li>memory/routes.js 依赖 service.js、tags.js、tier.js、embedding-config.js。</li><li>rag/routes.js 依赖 manager.js、embedding/index.js、errors.js、detect.js、install.js。</li><li>searcher.js 依赖 config.js、errors.js、keyword-match.js。</li></ul><pre class="mermaid">graph LR
Server[&quot;server.js&quot;] --&gt; MemoryRoutes[&quot;memory/routes.js&quot;]
Server --&gt; RagRoutes[&quot;rag/routes.js&quot;]
MemoryRoutes --&gt; MemoryService[&quot;memory/service.js&quot;]
MemoryService --&gt; Tags[&quot;memory/tags.js&quot;]
MemoryService --&gt; Tier[&quot;memory/tier.js&quot;]
RagRoutes --&gt; Searcher[&quot;rag/searcher.js&quot;]
Searcher --&gt; Config[&quot;rag/config.js&quot;]
Searcher --&gt; Errors[&quot;rag/errors.js&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L548" target="_blank" rel="noreferrer">agent/src/server.js#L417-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L4-L11" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L4-L11</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L22-L26" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L22-L26</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L11-L13" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L11-L13</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L548" target="_blank" rel="noreferrer">agent/src/server.js#L417-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L4-L11" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L4-L11</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L22-L26" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L22-L26</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L11-L13" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L11-L13</a></li></ul><h2 id="性能考虑" tabindex="-1">性能考虑 <a class="header-anchor" href="#性能考虑" aria-label="Permalink to &quot;性能考虑&quot;">​</a></h2><ul><li><strong>记忆侧</strong>： <ul><li>向量嵌入调用带 8 秒超时，失败降级到关键词通道。</li><li>懒补向量不 await，避免每次 store 增加网络往返。</li><li>recall 分三阶段：锁内只读、锁外补齐、锁内收尾，避免外部嵌入拖垮全进程。</li><li>标签在有查询时仅做名次加成，避免三个硬门槛叠加导致误杀。</li></ul></li><li><strong>RAG 侧</strong>： <ul><li>关键词扫描限制 KEYWORD_SCAN_LIMIT，超过则跳过关键词通道防止大库卡顿。</li><li>旁路探测放宽阈值区分“无数据”与“被过滤”。</li><li>多库检索 topK 按库均分，避免高得分库垄断结果。</li></ul></li><li><strong>通用</strong>： <ul><li>MAX_BODY_SIZE 限制 JSON body 大小。</li><li>流式上传支持二进制，避免 base64 膨胀。</li><li>认证冷却与操作防重入，防止 DoS。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L13-L14" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L13-L14</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L174-L187" target="_blank" rel="noreferrer">agent/src/memory/service.js#L174-L187</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L461-L740" target="_blank" rel="noreferrer">agent/src/memory/service.js#L461-L740</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L17-L21" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L17-L21</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L132-L136" target="_blank" rel="noreferrer">agent/src/server.js#L132-L136</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L792-L800" target="_blank" rel="noreferrer">agent/src/server.js#L792-L800</a></li></ul><h2 id="故障诊断指南" tabindex="-1">故障诊断指南 <a class="header-anchor" href="#故障诊断指南" aria-label="Permalink to &quot;故障诊断指南&quot;">​</a></h2><p>常见错误与处理方式：</p><ul><li><strong>401 未认证</strong>：缺少 Authorization: Bearer &lt;token&gt;。</li><li><strong>403 无效 Token</strong>：Token 校验失败。</li><li><strong>400 业务错误</strong>：参数缺失、JSON 解析失败、Multipart 解析失败、RAG 不支持类型、记忆注入模式拦截等。</li><li><strong>404 未知路径</strong>：记忆端点未匹配或 RAG 路径未匹配。</li><li><strong>500 内部错误</strong>：服务器异常兜底。</li><li><strong>embedding_timeout</strong>：向量服务响应超时，记忆侧自动降级关键词通道。</li><li><strong>vector_status_failed</strong>：向量状态查询失败。</li><li><strong>invalidEmbeddingMode</strong>：embedding 模式非法。</li><li><strong>rebuild recovery scan failed</strong>：RAG 重建恢复扫描失败。</li></ul><p>排查步骤：</p><ol><li>确认 Bearer Token 是否正确。</li><li>检查请求体是否为合法 JSON。</li><li>对于 RAG 导入，确认 type 是否在 text/file/url 中。</li><li>对于记忆写入，确认 action/type/content/importance 是否符合要求。</li><li>对于向量相关错误，检查 embedding-config 与 test-embedding 返回值。</li><li>查看进程日志中的 <code>[Memory] route error</code>、<code>[RAG] route error</code>、<code>[RAG] rebuild recovery scan failed</code> 等关键字。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L424" target="_blank" rel="noreferrer">agent/src/server.js#L417-L424</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L188-L191" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L188-L191</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L68-L79" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L68-L79</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L31-L34" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L31-L34</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>记忆管理与 RAG 检索共同构成 AI 助手的核心知识能力：记忆用于短期对话上下文之外的长期事实与摘要，RAG 用于结构化知识库的语义检索。两者都强调：</p><ul><li>可扩展的嵌入提供者（本地/远端）。</li><li>稳健的错误降级（向量失败不破坏关键词通道）。</li><li>清晰的 API 契约（认证、CORS、JSON 响应、错误码）。</li><li>可观测的状态（vector-status、rag/status、ingest/status）。</li></ul><p>在实际使用中，建议：</p><ul><li>首次启用向量通道后调用 <code>/api/memory/reindex</code> 重建缓存。</li><li>使用 <code>/api/rag/test-embedding</code> 验证远端向量服务连通性与维度。</li><li>合理设置 topK 与 threshold，平衡召回率与精确率。</li><li>定期使用 <code>/api/memory/manage?action=compact</code> 清理低价值记忆。</li></ul><h2 id="附录-api-参考" tabindex="-1">附录：API 参考 <a class="header-anchor" href="#附录-api-参考" aria-label="Permalink to &quot;附录：API 参考&quot;">​</a></h2><h3 id="记忆管理端点-1" tabindex="-1">记忆管理端点 <a class="header-anchor" href="#记忆管理端点-1" aria-label="Permalink to &quot;记忆管理端点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>主要参数</th><th>成功响应</th><th>失败响应</th></tr></thead><tbody><tr><td>POST</td><td><code>/api/memory/store</code></td><td>添加/更新/删除记忆</td><td>action, type, content, memoryId, tags, importance, sourceSessionId</td><td><code>{ success: true, message, memory/action/stats }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>POST</td><td><code>/api/memory/recall</code></td><td>查询记忆</td><td>query, tags, memoryType, limit, sessionId</td><td><code>{ success: true, message, results, total, query, tier, vectorMatched }</code></td><td>400 <code>{ success: false, error }</code></td></tr><tr><td>POST</td><td><code>/api/memory/manage</code></td><td>审查/压缩</td><td>action: review/compact</td><td><code>{ success: true, ... }</code></td><td>400 <code>{ success: false, error }</code></td></tr><tr><td>GET</td><td><code>/api/memory/embedding-config</code></td><td>获取嵌入配置</td><td>无</td><td><code>{ success: true, config }</code></td><td>400 <code>{ success: false, error }</code></td></tr><tr><td>POST</td><td><code>/api/memory/embedding-config</code></td><td>保存嵌入配置</td><td>mode, apiKey, modelName, dimensions</td><td><code>{ success: true, config }</code></td><td>400 <code>{ success: false, error }</code></td></tr><tr><td>POST</td><td><code>/api/memory/test-embedding</code></td><td>测试嵌入连通性</td><td>mode, apiKey, modelName, dimensions</td><td><code>{ success: true, dimensions }</code></td><td>400 <code>{ success: false, error }</code></td></tr><tr><td>GET</td><td><code>/api/memory/vector-status</code></td><td>向量缓存状态</td><td>无</td><td><code>{ success: true, ...data }</code></td><td>400 <code>{ success: false, error }</code></td></tr><tr><td>POST</td><td><code>/api/memory/reindex</code></td><td>重建向量缓存</td><td>无</td><td><code>{ success: true, indexed/skipped }</code></td><td>400 <code>{ success: false, error }</code></td></tr></tbody></table><h3 id="rag-检索端点-1" tabindex="-1">RAG 检索端点 <a class="header-anchor" href="#rag-检索端点-1" aria-label="Permalink to &quot;RAG 检索端点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>主要参数</th><th>成功响应</th><th>失败响应</th></tr></thead><tbody><tr><td>POST</td><td><code>/api/rag/search</code></td><td>跨知识库检索</td><td>collectionIds, query, topK, threshold</td><td><code>{ success: true, results, total, hasContext, fallback }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>POST</td><td><code>/api/rag/collections/{id}/search</code></td><td>单库检索</td><td>query, topK, threshold</td><td><code>{ success: true, results, total, hasContext, fallback }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>GET</td><td><code>/api/rag/collections</code></td><td>列出知识库</td><td>无</td><td><code>{ success: true, collections }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>POST</td><td><code>/api/rag/collections</code></td><td>创建知识库</td><td>name, description, embeddingConfig</td><td><code>{ success: true, collection }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>PUT</td><td><code>/api/rag/collections/{id}</code></td><td>更新知识库</td><td>name, description, embeddingConfig, chunkConfig</td><td><code>{ success: true, collection }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>DELETE</td><td><code>/api/rag/collections/{id}</code></td><td>删除知识库</td><td>无</td><td><code>{ success: true, ... }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>POST</td><td><code>/api/rag/collections/{id}/toggle</code></td><td>启用/停用</td><td>无</td><td><code>{ success: true, ... }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>GET</td><td><code>/api/rag/collections/{id}/stats</code></td><td>统计信息</td><td>无</td><td><code>{ success: true, stats }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>POST</td><td><code>/api/rag/collections/{id}/ingest</code></td><td>导入文档</td><td>type, metadata, chunkConfig, content/path/url</td><td><code>{ success: true, ... }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>GET</td><td><code>/api/rag/collections/{id}/ingest/status</code></td><td>导入进度</td><td>无</td><td><code>{ success: true, progress }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>GET</td><td><code>/api/rag/collections/{id}/documents</code></td><td>文档列表</td><td>无</td><td><code>{ success: true, documents }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>DELETE</td><td><code>/api/rag/collections/{id}/documents/{docId}</code></td><td>删除文档</td><td>无</td><td><code>{ success: true, ... }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>GET</td><td><code>/api/rag/status</code></td><td>RAG 能力与安装状态</td><td>无</td><td><code>{ success: true, available, install }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>POST</td><td><code>/api/rag/test-embedding</code></td><td>测试远端向量服务</td><td>mode, apiKey, modelName, dimensions</td><td><code>{ success: true, mode, model, dimensions }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>POST</td><td><code>/api/rag/install</code></td><td>安装 RAG 依赖</td><td>无</td><td><code>{ success: true, started }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr><tr><td>POST</td><td><code>/api/rag/detect</code></td><td>重新检测 RAG 依赖</td><td>无</td><td><code>{ success: true, available }</code></td><td>400 <code>{ success: false, error, code? }</code></td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L149-L199" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L149-L199</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/routes.js#L133-L282" target="_blank" rel="noreferrer">agent/src/rag/routes.js#L133-L282</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.zh-CN.md#L488-L510" target="_blank" rel="noreferrer">agent/README.zh-CN.md#L488-L510</a></li></ul>`,148)])])}const u=r(i,[["render",l]]);export{m as __pageData,u as default};
